INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (53421, 53026, 11961, 'Std User Workflow', 'Standard Manual User Approval Workflow', 'If selected, only documents with an open status (drafted, in progress, approved, rejected, invalid) and standard user actions (prepare, complete, approve, reject) are allowed to continue.  Use this to prevent having to define details on how automatic processes (unlock, invalidate, post, re-activate) and when the document is closed for normal user action (completed, waiting, closed, voided, reversed).', 80, 'Y', NULL, NULL, 'N', NULL, 'Y');
