INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (201817, 148, 53318, 'Document No', 'Document sequence number of the document', 'The document number is usually automatically generated by the system and determined by the document type of the document. If the document is not saved, the preliminary number is displayed in "<>".

If the document type of your document has no automatic document sequence defined, the field is empty if you create a new document. This is for documents which usually have an external number (like vendor invoice).  If you leave the field empty, the system will generate a document number for you. The document sequence used for this fallback number is defined in the "Maintain Sequence" window with the name "DocumentNo_<TableName>", where TableName is the actual name of the table (e.g. C_Order).', 0, 'N', NULL, NULL, 'N', NULL, 'Y');
