INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (2581, 167, 3392, 'SO Sub Type', 'Sales Order Sub Type', 'The SO Sub Type indicates the type of sales order this document refers to.  This field only appears when the Document Base Type is Sales Order.  The selection made here will determine which documents will be generated when an order is processed and which documents must be generated manually or in batches.  <br>
The following outlines this process.<br>
SO Sub Type of <b>Standard Order</b> will generate just the <b>Order</b> document when the order is processed.  <br>
The <b>Delivery Note</b>, <b>Invoice</b> and <b>Receipt</b> must be generated via other processes.  <br>
SO Sub Type of <b>Warehouse Order</b> will generate the <b>Order</b> and <b>Delivery Note</b>. <br> The <b>Invoice</b> and <b>Receipt</b> must be generated via other processes.<br>
SO Sub Type of <b>Credit Order</b> will generate the <b>Order</b>, <b>Delivery Note</b> and <b>Invoice</b>. <br> The <b>Receipt</b> must be generated via other processes.<br>
SO Sub Type of <b>POS</b> (Point of Sale) will generate all document', 120, 'Y', '@DocBaseType@=''SOO'' | @DocBaseType@=''POO''', NULL, 'N', NULL, 'Y');
