INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (62766, 53456, 2896, 'Active', 'The record is active in the system', 'There are two methods of making records unavailable in the system: One is to delete the record, the other is to de-activate the record. A de-activated record is not available for selection, but available for reports.
There are two reasons for de-activating and not deleting records:
(1) The system requires the record for audit purposes.
(2) The record is referenced by other records. E.g., you cannot delete a Business Partner, if there are invoices for this partner record existing. You de-activate the Business Partner and prevent that this record is used for future entries.', 70, 'Y', NULL, NULL, 'N', NULL, 'Y');
