INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (205833, 394, 213695, 'Display Logic', 'If the Field is displayed, the result determines if the field is actually displayed', 'format := {expression} [{logic} {expression}]<br> 
expression := @{context}@{operand}{value} or @{context}@{operand}{value}<br> 
logic := {|}|{&}<br>
context := any global or window context <br>
value := strings or numbers<br>
logic operators	:= AND or OR with the previous result from left to right <br>
operand := eq{=}, gt{&gt;}, le{&lt;}, not{~^!} <br>
Examples: <br>
<ul>
<li> @AD_Table_ID@=14 | @Language@!GERGER</li>
<li> @PriceLimit@>10 | @PriceList@>@PriceActual@</li>
<li> @Name@>J</li>
</ul>
Strings may be in single quotes (optional)', 160, 'Y', NULL, NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (200003, 394, 200018, 'Read Only Logic', 'Logic to determine if field is read only (applies only when field is read-write)', 'format := {expression} [{logic} {expression}]<br> 
expression := @{context}@{operand}{value} or @{context}@{operand}{value}<br> 
logic := {|}|{&}<br>
context := any global or window context <br>
value := strings or numbers<br>
logic operators	:= AND or OR with the previous result from left to right <br>
operand := eq{=}, gt{&gt;}, le{&lt;}, not{~^!} <br>
Examples: <br>
<ul>
<li> @AD_Table_ID@=14 | @Language@!GERGER</li>
<li> @PriceLimit@>10 | @PriceList@>@PriceActual@</li>
<li> @Name@>J</li>
</ul>
Strings may be in single quotes (optional)', 170, 'Y', NULL, NULL, 'N', NULL, 'Y');
