INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (206021, 200266, 213847, 'Preference Level', 'Determines what preferences the user can set', 'Preferences allow you to define default values.  If set to None, you cannot set any preference nor value preference. Only if set to Tenant, you can see the Record Info Change Log.', 0, 'N', NULL, NULL, 'N', NULL, 'Y');
