INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (1362, 199, 2480, 'History Days', 'Number of days to be able to post in the past (based on system date)', 'If Automatic Period Control is enabled, the current period is calculated based on the system date and you can always post to all days in the current period.  History Days enable to post to previous periods.  E.g. today is May 15th and History Days is set to 30, you can post back to April 15th', 160, 'Y', '@AutoPeriodControl@=''Y''', NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (10892, 135, 12916, 'Local Address Format', 'Format for printing this Address locally', 'The optional Local Address Print format defines the format to be used when this address prints for the Country.  If defined, this format is used for printing the address for the country rather then the standard address format.
 The following notations are used: @C@=City  @P@=Postal  @A@=PostalAdd  @R@=Region', 140, 'Y', NULL, NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (10891, 135, 12915, 'Reverse Local Address Lines', 'Print Local Address in reverse Order', 'If NOT selected the local sequence is Address 1, Address 2, Address 3, Address 4, City/Region/Postal, Country.
If selected the local sequence is Country, City/Region/Postal, Address 4, Address 3, Address 2, Address 1.
The sequence of City/Region/Postal is determined by the local address format.', 150, 'Y', NULL, NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (346, 135, 1227, 'Postal Code Format', 'Format of the postal code; Can contain fixed format elements, Variables: "_lLoOaAcCa09"', '<B>Validation elements:</B>
 	(Space) any character
_	Space (fixed character)
l	any Letter a..Z NO space
L	any Letter a..Z NO space converted to upper case
o	any Letter a..Z or space
O	any Letter a..Z or space converted to upper case
a	any Letters & Digits NO space
A	any Letters & Digits NO space converted to upper case
c	any Letters & Digits or space
C	any Letters & Digits or space converted to upper case
0	Digits 0..9 NO space
9	Digits 0..9 or space

Example of format "(000)_000-0000"', 160, 'Y', NULL, NULL, 'N', NULL, 'Y');
