INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (61776, 53406, 61629, 'Interval', 'How often? Days or usage between maintenance', 'Maintenance interval. For Calendar-based (C): number of days between maintenance runs. For Meter-based (M): usage units between maintenance (e.g., 5000 km, 250 hours).', 150, 'Y', NULL, NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (61777, 53406, 61639, 'Range', NULL, 'Tolerance range for maintenance due point. Maintenance is considered due when reading is within Next MP +/- Range.', 160, 'Y', '@ProgrammingType@=M', NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (61778, 53406, 61635, 'Next maintenance', 'At what reading is maintenance due?', 'Next meter point when maintenance is due. Calculated as Last MP + Interval. (Shows when Programming Type = M)', 170, 'Y', '@ProgrammingType@=M', NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (61779, 53406, 61637, 'Prom Use', NULL, 'Warning threshold (Prognosis Use). Triggers maintenance alert when current reading reaches Next MP minus this value.', 180, 'Y', '@ProgrammingType@=M', NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (61780, 53406, 61625, 'Date last run', 'Date the process was last run.', 'Date when this maintenance schedule was last executed. For Calendar-based maintenance, this is used with Interval to calculate Date Next Run. (Shows when Programming Type = C)', 190, 'Y', '@ProgrammingType@=C', NULL, 'N', NULL, 'Y');
INSERT OR IGNORE INTO AD_Field (ad_field_id, ad_tab_id, ad_column_id, name, description, help, seqno, isdisplayed, displaylogic, ismandatory, isreadonly, defaultvalue, isactive) VALUES (61781, 53406, 61626, 'Date next run', 'Date the process will run next', 'Date when this maintenance is next due. For Calendar-based maintenance, calculated as Date Last Run + Interval days. (Shows when Programming Type = C)', 200, 'Y', '@ProgrammingType@=C', NULL, 'N', NULL, 'Y');
