INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (356, 207, 'Commission Line', 'Define your commission calculation rule', 'Define the selection criteria for paying the commission. If you do not enter restricting parameters (e.g. for specific Business Partner (Groups) or Product (Categories), etc. all transactions for the period will be used to calculate the commission.

After converting from the transaction to the commission currency,
the formula for calculating the commission is:

(Converted Amount - Subtract Amount) * Amount Multiplier
+ (Actual Quantity - Subtract Quantity) * Quantity Multiplier

You can choose, that only positive amounts (Converted Amount - Subtract Amount) and positive quantities (Actual Quantity - Subtract Quantity) are used in the calculation.', 431, 1, 20, 'Y', 'N', NULL, NULL, 'Y');
