INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (468, 261, 'Attribute Search', 'Common Search Attribute ', 'Attributes are specific to a Product Attribute Set (e.g. Size for T-Shirts: S,M,L). If you have multiple attributes and want to search under a common sttribute, you define a search sttribute. Example: have one Size search attribute combining the values of all different sizes (Size for Dress Shirt  XL,L,M,S,XS). The Attribute Search allows you to have all values available for selection.  This eases the maintenance of the individual product attribute.', 564, 0, 10, 'Y', 'N', NULL, NULL, 'Y');
