INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (316, 189, 'Format Field', 'Maintain Format Fields', 'Define the individual field based on the table definition.  Please note that you have to make sure that a Constant has the correct  SQL data type (i.e. if it is a ''string'', you need to enclose it like ''this'').
<p>Product mapping (for details see documentation):
