INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (53286, 140, 'BOM', 'Bill of Material product lines', 'The Bill of Materials tab defines those products that are generated from other products.  A Bill of Material (BOM) is one or more Products or BOMs.

Available Quantity:
- Stored BOMs have to be created via "Production"
- The available quantity of a non-stored BOMs is dynamically calculated
- The attribute "Stored" is defined in the "Product" tab

Price:
- BOMs must be listed in Pricelists
- If the price is 0.00, the price is dynamically calculated

Printing:
- Usually, only the BOM information is printed
- For invoices, delivery slips and pick lists, you have the option to print the details
- In the details, the quantity is listed - and the price, if this is dynamically calculated', 53018, 1, 15, 'Y', 'N', NULL, NULL, 'Y');
