INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (426, 240, 'Format Item', 'Print Format Item', 'Item in the print format maintaining layout information.  The following additional variables are available when printing:
<p>@*Page@ - the current page number
<br>@*PageCount@ - the total number of pages
<br>@*MultiPageInfo@ - "Page x of y" - only printed if more than one page
<br>@*CopyInfo@ - if it is a copy of the document "Duplicate" is printed
<br>@*ReportName@ - name of the report
<br>@*Header@ - Full Header with user/tenant/org name and connection
<br>@*CurrentDate@ - the print date
<br>@*CurrentDateTime@ - the print time

<p>The layout logic for forms is: <br>
- if not printed: ignore <br>
- set New Line Position <br>
- new page <br>
- new line, if something was printed since last new line<br>
- format item<br>
- print it (if not null/empty selected)<br>
(i.e. suppress null does not prevent new line)', 489, 1, 40, 'Y', 'N', 'AD_PrintFormatItem.IsPrinted=''Y''', NULL, 'Y');
INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (200371, 200138, 'Test UU Based Table Trl', NULL, NULL, 200401, 1, 20, 'Y', 'N', NULL, 'TestUU_Trl.AD_Language', 'Y');
INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (482, 268, 'Table Access', 'Maintain Table Access', 'If listed here, the Role can(not) access all data of this table, even if the role has access to the functionality.
<br>If you Include Access to a table and select Read Only, you can only read data (otherwise full access).
<br>If you Exclude Access to a table and select Read Only, you can only read data (otherwise no access).
<br>Please note that table access rules here are in addition to the Data Access Levels defined for a Table and the User Level defined for a Role. These rules are evaluated first and you only need to define the exceptions to these rules here.
<p>
Note that access information is cached and requires re-login or reset of cache. Be aware that if you use Include rules, then you need to include also several supporting entities. As an alternative, grant access only to functionality required.', 565, 1, 20, 'Y', 'N', NULL, NULL, 'Y');
INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (508, 278, 'General Ledger', 'Import General Ledger', 'A new Journal Batch is created, if the Batch Document No or accounting schema are different. A new Journal is created, if the Document No, Currency, Document Type, GL Category, Posting Type or Accounting type is different. You can also force the creation of a new Batch or Journal by selecting the create new flag.<p>
Please note that there are three Organization Fields: The Document Organization is the owner of the document and set directly or per parameter default. The Organization is part of the accounting key and only required if no Valid Account Combination is specified; If not defined it is derived from the Document Organization. The Transaction Organization is part of the account combination.<br>
The optional balance check applies to the entire import, not for individual batches or journals.
<br>The document numbers will be overwritten if the document type is not set to manual sequences.', 599, 0, 10, 'Y', 'N', NULL, NULL, 'Y');
