INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (200399, 200158, 'Role', 'Define responsibility roles', 'Define the role and add the organizations the role has access to. You can give users access to this role and modify the access of this role to windows, forms, processes and reports as well as tasks. <br>
If the Role User Level is Manual, the assigned access rights are not automatically updated (e.g. if a role has a restricted number of Windows/Processes it can access). You need to add organizational access unless the role has access to all organizations. The SuperUser and the user creating a new role are assigned to the role automatically.  <br>
If you select an Organization Tree, the user has access to the leaves of  summary organizations.
Note: You cannot change the System Administrator role.', 156, 0, 10, 'Y', 'N', 'AD_Role.IsMasterRole=''Y''', NULL, 'Y');
INSERT OR IGNORE INTO AD_Tab (ad_tab_id, ad_window_id, name, description, help, ad_table_id, tablevel, seqno, issinglerow, isreadonly, whereclause, orderbyclause, isactive) VALUES (119, 111, 'Role', 'Define responsibility roles', 'Define the role and add the organizations the role has access to. You can give users access to this role and modify the access of this role to windows, forms, processes and reports as well as tasks. <br>
If the Role User Level is Manual, the assigned access rights are not automatically updated (e.g. if a role has a restricted number of Windows/Processes it can access). You need to add organizational access unless the role has access to all organizations. The SuperUser and the user creating a new role are assigned to the role automatically.  <br>
If you select an Organization Tree, the user has access to the leaves of  summary organizations.
Note: You cannot change the System Administrator role.', 156, 0, 10, 'Y', 'N', 'AD_Role.IsMasterRole=''N''', NULL, 'Y');
