-- §SEED_AD_Window rows=370
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (114, 'Task', 'Maintain Tasks', 'The Maintain Tasks window defines the different tasks used in workflows and the access level for those tasks.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (154, 'GL Budget', 'Maintain General Ledger Budgets', NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (189, 'Import Loader Format', 'Maintain Import Loader Formats', 'The Import Loader Format Window is used for defining the file layout for product information which will be imported.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (245, 'Interest Area', 'Interest Area or Topic', 'Interest Areas reflect interest in a topic by a contact. Interest areas can be used for marketing campaigns.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (385, 'Info Window', 'Define Info and search/select Window', 'The Info window is used to search and select records as well as display information relevant to the selection.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (334, 'Import Confirmations', 'Import Receipt/Shipment Confirmation Lines', 'Import Confirmation data of existing Receipt/Shipment Confirmations', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (112, 'Document Sequence', 'Maintain System and Document Sequences', 'The Sequence Window defines how document numbers will be sequenced.
Change the way document numbers are generated. You may add a prefix or a suffix or change the current number.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (128, 'Attachment', 'Maintain Attachments', 'For System Maintenance Only.  The Maintain Attachments window is used for diagnostic purposes to display the attributes of an attachment.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (116, 'Currency Rate', 'Maintain Currency Conversion Rates', 'The Conversion Rates window is used to define the conversion rates that will be used when converting document amounts from one currency to another. Note that only the multiply rate is used; The divide rate is for visualization only.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (282, 'Freight Category', 'Maintain Freight Categories', 'Freight Categories are used to calculate the Freight for the Shipper selected', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (241, 'Print Paper', 'Maintain Print Paper', 'Printer Paper Size, Orientation and Margins', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (117, 'Calendar Year and Period', 'Maintain Calendars Years Periods', 'The Calendar Year and Periods defines the calendars that will be used for period control and reporting. You can also define non-standard calendars (e.g. business year from July to June).', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (295, 'Currency Type', 'Maintain Currency Conversion Rate Types', 'The Currency Conversion Rate Type lets you define different type of rates, e.g. Spot, Corporate and/or Sell/Buy rates.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (131, 'GL Category', 'Maintain General Ledger Categories', 'The GL Category Window allows you to define categories to be used in journals.  These categories provide a method of optionally grouping and reporting on journals.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (294, 'UnPosted Documents', 'Unposted Documents', 'View unposted documents', 'Q', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (138, 'Tax Category', 'Maintain Tax Categories', 'The Tax Category Window is used to enter and maintain Tax Categories.  Each product is associated with a tax category which facilitates reacting changing tax rates.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (351, 'Position', 'Maintain Job Positions', 'Maintain internal (employee) or external positions', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (129, 'Preference', 'Maintain System Tenant Org and User Preferences', 'System Admin use only.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (304, 'Organization Type', 'Maintain Organization Types', 'Organization Type allows you to categorize your organizations for reporting purposes', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (238, 'Print Color', 'Maintain Print Color', 'Colors used for printing', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (233, 'Discount Schema', 'Maintain Trade Discount Schema', 'Trade discount schema calculates the trade discount percentage', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (286, 'Project (Lines/Issues)', 'Maintain Sales Order and Work Order Details', 'The Project Window is used to maintain details of Projects Lines and Issues across Phases/Tasks', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (215, 'Performance Measure', 'Define your Performance Measures', 'The Performance Measure Window allows you to define the rules and restrictions for performance measurement.  You can, for example, restrict performance measurement to sales for a certain product category for a defined time frame.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (217, 'Report Column Set', 'Maintain Financial Report Column Sets', 'The Report Column Set defines what data is printed in the columns of a report.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (218, 'Report Line Set', 'Maintain Financial Report Line Sets', 'The Line Set determines, which lines are printed in a Financial Report', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (236, 'Resource', 'Maintain Resources', 'Maintain your Resources. The product for the resource is automatically created and synchronized. Update Name, Unit of Measure, etc. in the Resource and don''t change it in the product.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (100, 'Table and Column', 'Maintain Tables and Columns', 'The Table and Column Window defines all tables with their columns', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (101, 'Reference', 'Maintain System References', 'The Reference Window defines field/display types and validations. This window is for System Admin use only.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (246, 'System', 'System Definition', 'Common System Definition - Only one Record - Do not add additional records.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (149, 'Marketing Campaign', 'Maintain Marketing Campaigns', 'The Marketing Campaign Window defines the start and end date for a campaign.  It also gives a running balance of the invoice amounts which referred to this campaign.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (242, 'Expenses (to be invoiced)', 'View expenses and charges not invoiced to customers', 'Before invoicing to customers, check the expense lines to be invoiced', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (366, 'Performance Ratio', 'Maintain Performance Ratios', 'Calculation instruction for a ratio', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (212, 'Performance Goal', 'Define Performance Goals', 'The Performance Goal Window allows you to define performance goals or all, a role or a user', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (105, 'Menu', 'Maintain Menu', 'The Maintain Menu Window defines the Menu which will display.  It is for System Admin use only.  The menu items that each user will see depends upon the security defined.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (345, 'Request Category', 'Maintain Request Category', 'Category or Topic of the Request ', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (365, 'Performance Benchmark', 'Performance Benchmark', 'Data Series to compare internal performance with (e.g. stock price, ...)', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (104, 'Message', 'Maintain Information and Error Messages', 'The Message Window defines the Message Text and Message Tips for each system generated message.  It is for System Admin use only.', 'M', 'Y');
