INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (152, 'Sales Region', 'Maintain Sales Regions', 'The Sales Region Window defines the different regions where you do business.  You can generate reports based on Sales Regions', 'M', 'Y');
