INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (151, 'Element', 'Maintain System Elements', 'The System Element Window is the Central Repository for Field Names Descriptions and Help/Comments', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (243, 'Print Table Format', 'Define Report Table Format', 'The Print Table Format lets you define how table header, etc. is printed. Please note that the Report Table FOrmat is cached to improve performance.', 'M', 'Y');
