INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (313, 'Partner Relation', 'Maintain Business Partner Relations', 'Business Partner Relation allow to maintain Third Party Relationship rules: who receives invoices for shipments or pays for invoices.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (120, 'Unit of Measure', 'Maintain Unit of Measure ', 'The Unit of Measure Window is used to define non monetary units of measure.  It also defines if conversion between units of measure are allowed and how they are to be performed. The system provides some automatic conversions between units of measures (e.g. minute, hour, day, working day, etc.) if they are not explicitly defined here.
Conversions need to be direct (i.e. if you have only a conversion between A-B and B-C, the system cannot convert A-C, you need to define it explicitly).', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200, 'Field Group', 'Define Field Group', 'The Field Group Window allows you to define subsections in a tab.  For System Admin use only.', 'M', 'Y');
