INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (250, 'System Translation Check', 'Check System Language Translations', 'Verify your language translations for selected entities. You should use Translation Export / Import for effective translation. This window allows you to check the translation of the main translation entities.', 'M', 'Y');
