INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (207, 'Commission', 'Maintain Commissions and Royalties', 'Define how and when you want the commissions to be calculated and to whom to pay it.
The Commissions Window allows you define how commissions and royalties will be paid. You can pay multiple commissions for the same order or invoice (e.g. to the person entering the transaction, to the person responsible for sale of the product (category) and or business partner (group).', 'M', 'Y');
