INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53004, 'Manufacturing Resource', 'Manufacturing Resource', 'A Manufacturing Resource is defined as anything required for production and its unavailability can affect the Production Plan. Manufacturing Resources can be: Plants, Production lines, Work Centers and Work Stations.

