INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (106, 'Language', 'Maintain Languages', 'The Language Window allows you to define multiple parallel language for users. This allows users to access the same data but have the windows, tabs and fields appear in different languages.
If a language is a System Language, you can change the User Interface to this language (after translation).  Otherwise the language is only used for printing documents.

For the language code, we suggest using the Java convention of country and language (e.g. fr_CN - Canadian French).

Verify the translation creates missing translation records. Start this process after creating a new language.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (125, 'Accounting Schema', 'Maintain Accounting Schema - For changes to become effective you must re-login', 'The Accounting Schema Window defines an accounting method and the elements that will comprise an account structure. Create and activate elements for detailed accounting for Business Partners, Products, Locations, etc.
Review and change the GL and Default accounts. The actual accounts used in transactions depend on the executing organization; Most of the information is derived from the context.', 'M', 'Y');
