INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (235, 'Expense Report', 'Time and Expense Report', 'The time and expense report allows you to capture time spent on a project, billable time and to claim expenses.', 'T', 'Y');
