INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (208, 'Project Reporting', 'Maintain Project Reporting Cycles', 'The Project Cycle Window defines the steps associated with a specific Project.
You may want to define several Project cycles to differentiate the different types of projects. Project cycles may use all or a subset of the used Project Status (e.g. Your opportunity project cycle may include the steps from prospect to contract - the service cycle may include steps from installation to customer acceptance.', 'M', 'Y');
