INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (327, 'Counter Document', 'Maintain Counter Document Types', 'When using explicit documents for inter-org transaction (after linking a Business Partner to an Organization), you can determine what document type the counter document is based on the document type of the original transaction.  Example: a "Standard Order" creates a "Standard PO". 
If you define a relationship here, you overwrite the default counter document type in the Document Type definition. This allows you to define a specific mapping.
If not defined, the first matching document type is used (e.g. AR Invoice - first AP Invoice document type)', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (141, 'Payment Term', 'Maintain Payment Terms', 'The Payment Terms Window defines the different payment terms that you offer your customers and that are offered to you by your vendors.  Each invoice must contain a Payment Term.  On the standard invoice, the Name and the Document Note of the Payment Term is printed.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (265, 'Project Type', 'Maintain Project Type and Phase', 'Maintain Project Types and their Phases with standard performance information', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53005, 'Manufacturing Workflows', 'Maintain Manufacturing Workflows (Routing)', 'Manufacturing Workflows (Routing) is a set of information detailing the method of manufacture of a particular item .It includes the operations to be performed their sequence the various work centers to be involved and the standards for setup and run. In some companies routing also includes information on tooling operator skill levels inspection operationstesting requirements etc.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53046, 'Transfer Asset Entry', 'Create Transfer Asset Entry', 'The Transfer Asset Entry window allows you to create and post asset transfers to the GL', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (252, 'Asset Group', 'Group of Assets', 'The group of assets determines default accounts.  If a asset group is selected in the product category, assets are created when delivering the asset.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53008, 'MRP Notice', 'View MRP Notices', 'The system creates messages while performing processes. In this window you can view them.

MRP Notice
It is a group of messages generated for the MRP process. It indicates to the scheduler the actions he needs to do to reach the Master Production Schedule. The action messages are set as notices for the planner when he sign up the Compiere session.

The possible action messages are:

MRP Code	 Action Message
MRP - 001	 Beginning Quantity Less Than Zero.
MRP - 020	 Create - A Supply Order should be created to satisfy a negative projected on hand balance.
This message is only generate if Create Plan is No or if a new requirement appears the time fence.

MRP - 030	 De Expedite - Indicates that a scheduled supply order is due before it is needed
and should be delayed, or demand rescheduled to an earlier date.

MRP - 040	 Expedite - Indicates that a scheduled supply order is due after is needed
and should be rescheduled to an earlier date, or demand rescheduled to a later date.

MRP - 050	 Cancel - Indicate that a scheduled supply order is no longer needed and should be deleted.
MRP - 060	 Release Due For - Indicate that a schedule order should be released.
MRP - 070	 Release Past Due For - Indicate that a supply order was not released when it was due,
and should be either released or expedited now, or the demand rescheduled for a later date.

MRP - 080	 Quantity Less than Minimum - Indicates that a supply order was created for
a quantity less than the minimum quantity set in the product planning

MRP - 090	 Quantity Less than Maximum - Indicates that a supply order was created for a quantity
for a quantity greater than than maximum quantity set in the product planning

MRP - 100	 Past Due Time Fence - Indicates that there is an unsatisfied material requirement inside
the planning time fence for this item. You should either manually schedule and expedite orders to

fill this demand or delay fulfillment of the requirement that created the demand.

MRP - 110	 No exists Dem', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53085, 'MRP Notice (all)', 'View all MRP Notices', 'The system creates notices will running MRP process. In this window you can view them.
