INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (381, 'Entity Type', 'Maintain System Entity Type', 'The entity type determines the ownership of Application Dictionary entries.  The types "Dictionary" and "iDempiere" should not be used and are maintainted by iDempiere (i.e. all changes are reversed during migration to the current definition).', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (363, 'System Issue Report', 'Automatically created or manually entered System Issue Reports', 'System Issues are created to speed up the resolution of any system related issues (potential bugs).  If enabled, they are automatically reported to iDempiere.  No data or confidential information is transferred.', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (194, 'Bank/Cash Statement', 'Process Bank Statements', 'The Process Bank Statements window allows you to reconcile your Bank Statements.  You can either enter the line items from the statement in the Statement Line tab or select the ''Create From'' button to automatically generate the statement from all unreconciled payments to this bank account.  Once you have completed reconciling, select the ''Process Statement'' button to mark the payments as reconciled and update the appropriate GL accounts.', 'T', 'Y');
