INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (206, 'Payment Selection', 'Select Invoices for Payment', 'The Payment Selection Window allows you to select and process the invoices you want to pay.
(a) You can create a Payment Selection and select the invoices manually or generate the suggestions based on criteria.  You can change the amount to be paid or delete invoices, you do not want to pay.

(b) If you are happy with the Payment Selection, you create the payments.

(c) You print or export your payments in the Window Payment Print/Export', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (280, 'Import Payment', 'Import Payments', NULL, 'M', 'Y');
