INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (170, 'Inventory Move', 'Inventory Move', 'The Inventory Move Window allows you to move inventory from one location or warehouse to another.  After the appropriate lines are entered selecting the ''Process Movements'' button will adjust the inventory.', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200110, 'Info Window Customization', 'Define Info Window Customization for Role/User', 'The customization values defined here overwrite/replace the default system definition if defined.', 'M', 'Y');
