INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (108, 'User', 'Maintain Users of the system', 'The User Window allows you to maintain User of the system.  Users can log into the system and have access to functionality via one or more roles.  A user can also be a business partner contact.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53121, 'Import Inventory Move', 'This window allow import Inventory Move transaction', NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (278, 'Import GL Journal', 'Import General Ledger Journals', 'You way want to check the balance of the import with "Validate Only" before importing. 
Unbalanced Journals are imported; the handling is based on your settings for the posting process. The optional balance check checks the entire import, not individual batches and journals.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53134, 'Cash Plan', NULL, NULL, 'T', 'Y');
