INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (338, 'POS Terminal', 'Maintain your Point of Sales Terminal', 'The POS Terminal defines the defaults and functions available for the POS Form', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200108, 'All Roles', 'Roles from All Tenants', NULL, 'Q', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (111, 'Role', 'Maintain User Responsibilities', 'The Role Window allows you to define the different roles that users of this system will have.  Roles control access to windows, tasks, reports, etc. For a tenant an Administrator and User role are predefined. You may add additional roles to control access for specific functionality or data.
You can add users to the role.
Note that access information is cached and requires re-login or reset of cache.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200123, 'Drill Rule', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (146, 'Price List', 'Maintain Product Price Lists', 'The Price List Window allows you to generate product price lists for your Business Partners.  Price lists determine currency and tax treatment.  Price list versions allow to maintain parallel lists for different date ranges.  The most current pricelist version is used based on the document date.
<BR>
All pricelists have three prices: List, Standard and Limit
<BR>
First step is to create a base price list.  You can manually add products and enter the prices or create them automatically.  The base price list is often the purchase price list with list price (''official'' retail price), the standard price (your purchase price).  The limit price can be used to check your final purchase costs after discounts, rebates, etc.
<BR> 
Pricelists can be calculated and copied.  To speed up the calculation, the parameters are stored an used when creating a new price list version.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53071, 'Import Price List', 'Import Price Lists', 'The Import Price List Window is an interim table which is used when importing external data into the system.  Selecting the ''Process'' button will either add or modify the appropriate records.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (132, 'GL Journal Batch', 'Enter and change Manual Journal Entries', 'The GL Journal Window allows you to enter and modify manual journal entries', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200005, 'GL Journal', 'Enter and change Manual Journal Entries', 'The GL Journal Window allows you to enter and modify manual journal entries', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (130, 'Project', 'Maintain Projects', 'The Project Window is used to define the projects which will can be tracked by phases and tasks.', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (140, 'Product', 'Maintain Products', 'The Product Window defines all products used by an organization.  These products include those sold to customers, used in the manufacture of products sold to customers and products purchased by an organization.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (281, 'Import Order', 'Import Orders', 'Please set Y/N selections in the import loader format explicitly (e.g. as constants) and no not leave them NULL. A NULL value stands for "don''t know".
In general, selection boxes are not selected if the value is not "Y" (i.e. could be null or any other value). All tests are made on "Y" or "not Y" - i.e. NULL values are not "not Y", but NULL (don''t know) - see SQL Language introductions.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (283, 'Accounting Dimensions', 'Maintain Non-Account Dimension Trees', 'Maintain Trees of non account segment trees.  Account segment trees (as well as user defined dimensions) are mainatained in the Account Element window. Please note that you will not be able to create new entities in this window if you have not default set for all manfatory values!', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (275, 'Invoice Payment Schedule', 'Maintain Invoice Payment Schedule', 'Maintain Payment Schedule of unpaid invoices', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (181, 'Purchase Order', 'Manage Purchase Orders', 'The Purchase Order Window defines a purchase order for an organization.  When a Purchase Order has been entered you can generate a Shipment Document or Invoice from this Purchase Order', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (291, 'Business Partner Info', 'Document Information of Business Partners', NULL, 'Q', 'Y');
