INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (183, 'Purchase Invoice and Credit/Debit Note', 'Vendor Purchase Invoice and Credit/Debit Note', 'The Vendor Invoice Window allows you to display and enter Invoices from a Vendor.  Vendor Invoices can also be generated from Purchase Orders or Delivery Receipts.', 'T', 'Y');
