INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (314, 'RfQ Topic', 'Maintain RfQ Topics and Subscribers', 'A Request for Quotation Topic allows you to maintain a subscriber list of potential Vendors to respond to RfQs', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53026, 'Export Processor', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53053, 'Post Depreciation Entry', 'Create Depreciation Entry', 'The Depreciation Entry window allows you to create and post the depreciation expense entry to the GL', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (300, 'Registration Attributes', 'Asset Registration Attributes', 'Define the individual values for the Asset Registration', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (174, 'Revenue Recognition', 'Revenue Recognition Rules', 'The Revenue Recognition Window defines the intervals at which revenue will be recognized. Alternatively, the revenue recognition may be linked to service levels provided.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53154, 'Sales Stage', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53067, 'Web Service Definition', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200130, 'Label Assignment', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (213, 'Performance Measure Calculation', 'Define how you calculate your performance measures', 'The Performance Measure Calculation defines how performance measures will be calculated.
The sql needs to return a single value.  Please check examples.<br>
The date restriction is defined in the Goal.
Any restrictions for Organizations, Business Partners, Products, etc. are as Performance Goal Restrictions.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (109, 'Tenant', 'Maintain Tenants', 'The Tenant is the highest level of an independent business entity.  Each Tenant will have one or more Organizations reporting to it.  Each Tenant defines the accounting parameters (Accounting Schema, Tree definition, Non Monetary UOM''s). To create new Tenants, run the Initial Tenant Setup with the System Administrator Role.
Do not create a new tenant in this window, but use "Initial Tenant Setup" to set up the required security and access rules. If you create a new tenant here, you will not be able to view it and also the required tenant infrastructure would not have been set up.', 'M', 'Y');
