INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200095, 'Process Customization', 'Define Process Customization for Role/User', 'The customization values defined here overwrite/replace the default system definition if defined.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200132, 'SSO Configuration', 'Single sign-on Configuration', 'Single sign-on is an authentication scheme that allows a user to log in with a single ID to any of several related, yet independent, software systems.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200138, 'Test UU Based Table', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200139, 'Test UU Detail', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200140, 'Document Base Type Group', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200141, 'Model Generator Template', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53006, 'Bill of Materials and Formula', 'Maintain Product Bill of Materials & Formula', 'It is a list of all the subassemblies, intermediates, parts and raw material that go into a parent assembly showing the quantity of each required to make an assembly. There are a variety of display formats of bill of material, including single level bill of material, indented bill of material, modular (planning), costed bill of material, etc. May also be called "formula", "recipe", "ingredients list" in certain industries.
It answers the question, what are the components of the product?', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (165, 'Report and Process', 'Maintain Reports & Processes', 'The Report & Process Window is used to define the parameters and access rules for every Report and Process within the system.  This window is for System Admin use only.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (139, 'Warehouse and Locators', 'Maintain Warehouses and Locators', 'The Warehouse and Locators Window defines each Warehouse, any Locators for that Warehouse and the Accounting parameters to be used for inventory in that Warehouse.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (102, 'Window, Tab and Field', 'Maintain Windows, Tabs & Fields', 'The Window, Tab & Field Window defines the presentation of tables and columns within each window.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (341, 'Inventory Decrease/Increase', 'Enter Inventory Decrease/Increase (for example Internal Use of Inventory)', 'The Internal Use of Inventory Window allows enter the quantity of used products.', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (195, 'Payment and Receipt', 'Process Payments and Receipts', 'The Process Payments Window allows you to enter payments and reaipts for invoices.  If the payment is for a single invoice then it can be processed here.  If it is for multiple invoices or is a partial payment then it should be processed in the Payment Allocation Window.', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (167, 'Sales Invoice and Credit/Debit Note', 'Customer Sales Invoice and Credit/Debit Note', 'The Customer Invoice Window allows you to display and enter invoices for a customer.  Invoices can also be generated from Sales Orders or Delivery documents.', 'T', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (118, 'Account Element (Chart of Accounts)', 'Maintain Account Elements', 'The Account Element Window is used to define and maintain the Accounting Element and User Defined Elements. 
One of the account segments is your natural account segment (Chart of Account). You may add a new account element for parallel reporting or for user defined accounting segments.', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200147, 'Private Access', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200150, 'Dynamic Validation per Table', NULL, NULL, 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (158, 'Bank/Cash', 'Maintain Bank/Cash', 'The Bank/Cash Window is used to define the banks and accounts associated with an organization or business partner', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (360, 'Reporting Hierarchy', 'Define Reporting Hierarchy', 'Reporting Hierarchy allows you to select different Hierarchies/Trees for the report.
Accounting Segments like Organization, Account, Product may have several hierarchies to accommodate different views on the business', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (364, 'Performance Color Schema', 'Maintain Performance Color Schema', 'Visual representation of performance by color.  The Schema has often three levels (e.g. red-yellow-green).  iDempiere supports two levels (e.g. red-green) or four levels (e.g. gray-bronce-silver-gold).  Note that Measures without a goal are represented white.  The percentages could be between 0 and unlimited (i.e. above 100%).', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (53061, 'Depreciation Calculation Method', 'Define Calculation Methods used in depreciation expense calculation', 'The Depreciation Calculation Method window allows the user to define how adjustments to the fixed asset depreciation expense are handled', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (224, 'Print Form', 'Maintain Print Forms (Invoices, Checks, ..) used', 'Define the documents you use for this Tenant/Organization.  Note that the check format is defined in the Bank (Account) Window.<p>
The highest priority has the Print Format you define on a Document Type (example specific Export Invoice format). The next level is the set of Print Formats you defined for the organization of the document printed. The default is the set of Print Formats defines for all organizations of the Tenant (Organization=*).', 'M', 'Y');
INSERT OR IGNORE INTO AD_Window (ad_window_id, name, description, help, windowtype, isactive) VALUES (200151, 'Theme Customization', NULL, NULL, 'M', 'Y');
